using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageGeneratedCodeTests
{
    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            [MessagePackObject]
            public class IntKeyed
            {
                [Key(0)]
                public int A { get; set; }

                [Key(1)]
                public Color C { get; set; }
            }

            [MessagePackObject(true)]
            public class StringKeyed
            {
                public int B { get; set; }
            }

            public enum Color
            {
                Red,
                Green,
            }

            [Union(0, typeof(UnionA))]
            public interface IUnion
            {
            }

            [MessagePackObject]
            public class UnionA : IUnion
            {
                [Key(0)]
                public int X { get; set; }
            }

            [GeneratedMessagePackResolver]
            partial class MyResolver
            {
            }
        }
        """;

    [Fact]
    public async Task AllGeneratedFormattersAreExcludedFromCodeCoverage()
    {
        List<INamedTypeSymbol> types = await GetGeneratedTypesAsync();
        List<INamedTypeSymbol> formatters = types.Where(IsFormatter).ToList();
        Assert.NotEmpty(formatters);
        Assert.All(formatters, f => Assert.True(HasExcludeFromCodeCoverage(f), f.ToDisplayString()));
    }

    [Fact]
    public async Task GeneratedResolverIsExcludedFromCodeCoverage()
    {
        List<INamedTypeSymbol> types = await GetGeneratedTypesAsync();
        INamedTypeSymbol resolver = types.First(t => t.Name == "MyResolver");
        Assert.True(HasExcludeFromCodeCoverage(resolver), resolver.ToDisplayString());
    }

    [Fact]
    public async Task StringKeyEnumAndUnionFormattersAreExcludedFromCodeCoverage()
    {
        List<INamedTypeSymbol> types = await GetGeneratedTypesAsync();
        foreach (string dataTypeName in new[] { "StringKeyed", "Color", "IUnion" })
        {
            INamedTypeSymbol? formatter = types.FirstOrDefault(t => FormatsType(t, dataTypeName));
            Assert.True(formatter is not null, "No generated formatter for " + dataTypeName);
            Assert.True(HasExcludeFromCodeCoverage(formatter!), formatter!.ToDisplayString());
        }
    }

    private static bool IsFormatter(INamedTypeSymbol symbol)
        => symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter" && i.TypeArguments.Length == 1);

    private static bool FormatsType(INamedTypeSymbol symbol, string dataTypeName)
        => symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter" && i.TypeArguments.Length == 1 && i.TypeArguments[0].Name == dataTypeName);

    private static bool HasExcludeFromCodeCoverage(INamedTypeSymbol symbol)
        => symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute");

    private static async Task<List<INamedTypeSymbol>> GetGeneratedTypesAsync()
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = framework.Cast<MetadataReference>()
            .Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack).Cast<MetadataReference>())
            .ToList();
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsCoverageAssembly",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new global::MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.WithUpdatedParseOptions(parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);

        Assert.DoesNotContain(generatorDiagnostics, d => d.Severity == DiagnosticSeverity.Error);
        Assert.DoesNotContain(output.GetDiagnostics(), d => d.Severity == DiagnosticSeverity.Error);

        List<INamedTypeSymbol> result = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in output.SyntaxTrees.Skip(compilation.SyntaxTrees.Length))
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax decl in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(decl) is INamedTypeSymbol symbol)
                {
                    result.Add(symbol);
                }
            }
        }

        return result;
    }
}

